  String error(AppError error) {
    final family = '${error.code.split('.').first}.generic';
    var value = _errorTranslations[language.code]?[error.code] ??
        _errorTranslations[language.code]?[family] ??
        _errorTranslations[language.code]?['common.unexpected'] ??
        _errorTranslations['uk']?[error.code] ??
        _errorTranslations['uk']?[family] ??
        _errorTranslations['uk']?['common.unexpected'] ??
        'Error';
    for (final entry in error.parameters.entries) {
      value = value.replaceAll('{${entry.key}}', entry.value?.toString() ?? '');
    }
    return value;
  }

  String text(String key) =>
      _translations[language.code]?[key] ??
      _calculatorTranslations[language.code]?[key] ??
      _workflowTranslations[language.code]?[key] ??
      _plannerTranslations[language.code]?[key] ??
      _translations['uk']?[key] ??
      _calculatorTranslations['uk']?[key] ??
      _workflowTranslations['uk']?[key] ??
      _plannerTranslations['uk']?[key] ??
      key;
}
